async function legacyExportItems(editions){
 if(editions.length>100)throw Error('Export up to 100 selected editions at a time, or use the complete collection archives.');
 const files=[];for(const e of editions){document.querySelector('#busy b').textContent='Preparing edition '+e+'…';const a=await studio.repo.item(e),dir=String(e).padStart(4,'0')+'/';files.push([dir+'art.txt',a.ascii],[dir+'metadata.json',JSON.stringify(a.metadata,null,2)],[dir+'dna.json',JSON.stringify(a.dna,null,2)],[dir+'scene.json',JSON.stringify({scene:a.scene,config:a.cfg})]);const png=await fetch('/collection/previews/'+String(e).padStart(4,'0')+'.png').then(r=>r.arrayBuffer());files.push([dir+'preview.png',new Uint8Array(png)]);}
 save(zip(files),'null-genesis-editions.zip','application/zip');
}
