function draw(){if(current?.genome?.genome_version==='web-4.5.0'&&asciiFont){let canvas=$('animation-canvas');if(!canvas.dataset.gpu){const next=canvas.cloneNode(false);next.dataset.gpu='true';canvas.replaceWith(next);canvas=next;asciiPlayer=new AsciiDisplay(canvas,asciiFont);}asciiPlayer.draw(anim?anim.frames[frame]:current.ascii,anim?anim.luminance[frame]:current.luminance,gridOf(current),Number($('presentation-size').value),$('show-grid').checked);$('timeline').value=frame;$('frame-label').textContent=frame+' / '+(anim?anim.frames.length-1:0);$('timeline-seconds').textContent=(frame/(anim?.fps||12)).toFixed(2)+' SEC';return;}if($('animation-canvas').dataset.gpu){const old=$('animation-canvas'),next=old.cloneNode(false);delete next.dataset.gpu;asciiPlayer?.dispose();old.replaceWith(next);}const canvas=$('animation-canvas'),[w,h]=current?gridOf(current):[80,80],square=current?.genome?.genome_version==='web-4.5.0';canvas.width=square?600:w*13;canvas.height=square?600:h*24;const ctx=canvas.getContext('2d');ctx.fillStyle='#050505';ctx.fillRect(0,0,canvas.width,canvas.height);if(!current)return;const chars=(anim?anim.frames[frame]:current.ascii).replaceAll('\n',''),levels=anim?anim.luminance[frame]:current.luminance,cw=canvas.width/w,ch=canvas.height/h;ctx.font=ch+'px Consolas,monospace';ctx.textBaseline='top';for(let i=0;i<w*h;i++){const v=Math.round(levels[i]);ctx.fillStyle=`rgb(${v},${v},${v})`;ctx.fillText(chars[i],i%w*cw+(square?cw*.22:0),Math.floor(i/w)*ch);}if($('show-grid').checked){ctx.strokeStyle='#ffffff16';ctx.lineWidth=.5;for(let x=0;x<=w;x++){ctx.beginPath();ctx.moveTo(x*cw,0);ctx.lineTo(x*cw,canvas.height);ctx.stroke();}for(let y=0;y<=h;y++){ctx.beginPath();ctx.moveTo(0,y*ch);ctx.lineTo(canvas.width,y*ch);ctx.stroke();}}$('timeline').value=frame;$('frame-label').textContent=frame+' / '+(anim?anim.frames.length-1:0);$('timeline-seconds').textContent=(frame/(anim?.fps||12)).toFixed(2)+' SEC';}

