async function exportItems(editions){if(editions.length>100)throw Error('Export up to 100 selected editions, or download complete archives.');const files=[];for(const e of editions){$('busy').querySelector('b').textContent='Preparing edition '+e+'…';const p=await studio.api('/api/item?edition='+e),dir=String(e).padStart(4,'0')+'/';files.push([dir+'art.txt',p.ascii],[dir+'metadata.json',JSON.stringify(metadata(p),null,2)],[dir+'dna.json',JSON.stringify(p.dna||p.genome,null,2)]);if(p.genome?.scene)files.push([dir+'scene.json',JSON.stringify({scene:p.genome.scene,config:p.genome.config,grid:gridOf(p)})]);const r=await fetch(p.preview);if(!r.ok)throw Error('Edition preview export failed.');files.push([dir+'preview.png',new Uint8Array(await r.arrayBuffer())]);if(studio.release==='v45'){const q=await readJson(metadata(p).quality_record),data=await readJson(metadata(p).media.frames);files.push([dir+'quality.json',JSON.stringify(q)],[dir+'animation.frames.json',JSON.stringify(data)],[dir+'animation.html',animationDocument(data,asciiFont)]);for(const ext of ['mp4','webm']){const url=metadata(p).media[ext];if(url){const video=await fetch(url);if(!video.ok)throw Error('Legendary video export failed.');files.push([dir+'animation.'+ext,new Uint8Array(await video.arrayBuffer())]);}}}}save(zip(files),'null-genesis-editions.zip','application/zip');}
async function allExports(){const path=studio.release!=='legacy'?'/'+studio.release+'/collection/exports/index.json':'/exports/index.json',r=await fetch(path);if(!r.ok)throw Error('This release has no completed export archives yet.');const manifest=await r.json(),list=Array.isArray(manifest)?manifest:manifest.archives||manifest.parts||[];$('archive-list').replaceChildren(...list.map(item=>{const a=document.createElement('a');a.className='file-button';a.href=item.url;a.download=item.name||item.file||'';a.textContent=(item.label||item.name||item.file)+' · '+(item.megabytes||item.size_mb||(item.bytes/1048576).toFixed(1))+' MB';return a;}));$('archive-dialog').querySelector('p').textContent='Public exports include native ASCII, grayscale previews, metadata and DNA. Owner keys are excluded.';$('archive-dialog').showModal();}
function animationHTML(a){if(current?.genome?.genome_version==='web-4.5.0')return animationDocument({...a,presentation:[Number($('presentation-size').value),Number($('presentation-size').value)]},asciiFont);const payload=JSON.stringify({...a,grid:gridOf(current)}).replace(/</g,'\\u003c');return '<!doctype html><meta charset="utf-8"><title>NULL GENESIS</title><style>body{background:#111;color:#ccc;font:13px monospace;text-align:center}canvas{display:block;margin:20px auto;height:80vh;max-width:100%;background:#050505}button,input{margin:8px;accent-color:#ccc}</style><h1>NULL GENESIS</h1><canvas id="c"></canvas><button id="play">Pause</button><input id="t" type="range" min="0"><script>const a='+payload+';let n=0,p=true;const c=document.querySelector("#c"),x=c.getContext("2d"),t=document.querySelector("#t"),w=a.grid[0],h=a.grid[1];c.width=a.presentation?600:w*13;c.height=a.presentation?600:h*24;t.max=a.frames.length-1;function draw(){x.fillStyle="#050505";x.fillRect(0,0,c.width,c.height);x.font=(c.height/h)+"px Consolas,monospace";x.textBaseline="top";const s=a.frames[n].split("\\n").slice(0,h).join("");for(let i=0;i<w*h;i++){let v=Math.round(a.luminance[n][i]);x.fillStyle="rgb("+v+","+v+","+v+")";x.fillText(s[i],i%w*(c.width/w)+(a.presentation?c.width/w*.22:0),Math.floor(i/w)*(c.height/h))}t.value=n}document.querySelector("#play").onclick=e=>{p=!p;e.target.textContent=p?"Pause":"Play"};t.oninput=()=>{p=false;n=+t.value;draw()};draw();setInterval(()=>{if(p){n=(n+1)%a.frames.length;draw()}},1000/a.fps);<\/script>';}
async function recordVideo(format){const mime='video/'+format;if(!window.MediaRecorder||!MediaRecorder.isTypeSupported(mime))throw Error('This browser cannot encode '+format.toUpperCase()+'. Export HTML or native frames.');const old=frame;playing=false;frame=0;draw();const stream=$('animation-canvas').captureStream(anim.fps),recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:5000000}),chunks=[];recorder.ondataavailable=e=>e.data.size&&chunks.push(e.data);const done=new Promise(resolve=>recorder.onstop=resolve);try{recorder.start();for(let i=0;i<anim.frames.length;i++){frame=i;draw();$('busy').querySelector('b').textContent='Recording frame '+(i+1)+' / '+anim.frames.length;await new Promise(r=>setTimeout(r,1000/anim.fps));}recorder.stop();await done;save(new Blob(chunks,{type:mime}),'null-genesis.'+format,mime);}finally{stream.getTracks().forEach(t=>t.stop());frame=old;draw();}}
$('engine-version').onchange=()=>{const v=$('engine-version').value;options('native-grid',(v==='4.5.0'?[30,50,64,80,96,120]:[30,50]).map(n=>[String(n),n+' × '+n]),v==='4.5.0'?'80':'50');for(const c of CATEGORIES)options('cat-'+c,[['','Deterministic synthesis'],...registry.traits.filter(t=>t.category===c&&(v==='4.5.0'||t.id.startsWith('V3.'))).map(t=>[t.id,t.label])]);versionControls();};$('rarity').onchange=versionControls;$('appearance').onchange=versionControls;$('motion-intensity').oninput=()=>$('motion-intensity-out').value=Number($('motion-intensity').value).toFixed(2);$('nft-trait-search').oninput=traitExplorer;$('experiment-search').oninput=experiments;$('experiment-grid').onchange=experiments;
$('release-picker').onchange=()=>task(async()=>{studio.setRelease($('release-picker').value);page=0;selected.clear();await status();await recent();collection();traitExplorer();analytics();packet(await studio.api('/api/item?edition=1'),1);});
$('regenerate').onclick=()=>current&&task(async()=>{const input=current.dna?.algorithm?current.dna:current.genome;packet(await studio.api(input.algorithm?'/api/decode':'/api/regenerate',input.algorithm?{envelope:input}:{genome:input}),edition);});$('reveal').onclick=()=>current&&task(async()=>{if(current.dna?.algorithm&&!current.genome?.scene){packet(await studio.api('/api/decode',{envelope:current.dna}),edition);return;}show('animation');$('legend-choice').value='';await loadAnimation();});
$('preview-mode').onchange=()=>task(async()=>{if(!current)return;const mode=$('preview-mode').value;if(mode==='canonical'){$('lab-art').src=current.preview;$('ascii-preview').textContent=current.ascii;return;}let data=current.data;if(!data){if(!current.genome?.scene)throw Error('Unlock this edition’s DNA to inspect hidden geometry.');data=await studio.engine.render(current.genome);}const diagnostic=diagnosticCells(data,mode,current.genome);$('lab-art').src=await studio.engine.image(diagnostic,current.genome);$('ascii-preview').textContent=toAscii(diagnostic);});$('ascii-scale').onchange=()=>{$('ascii-preview').style.fontSize=12*Number($('ascii-scale').value)+'px';$('ascii-preview').style.lineHeight=20*Number($('ascii-scale').value)+'px';};
$('export-animation').onclick=()=>task(async()=>{if(!anim)await loadAnimation();const format=$('animation-format').value;if(format==='frames'){save(JSON.stringify({...anim,grid:gridOf(current)}),'null-genesis.frames.json','application/json');return;}if(format==='html'){save(animationHTML(anim),'null-genesis.animation.html','text/html');return;}const m=metadata(current),stored=studio.release!=='legacy'?(m.animation?.[format]||m.media?.[format]):edition&&m.rarity==='LEGENDARY'?'/collection/animations/'+String(edition).padStart(4,'0')+'.'+format:null;if(stored){const r=await fetch(stored);if(!r.ok)throw Error('Stored video could not be loaded.');save(await r.blob(),'null-genesis.'+format,'video/'+format);return;}await recordVideo(format);});
task(async()=>{asciiFont=await AsciiDisplay.font();studio=await new Studio().init();cfg=await studio.api('/api/config');registry=cfg.registry45;recipes=cfg.recipes45;options('family',cfg.families.map(f=>[f,f]),'SKULLS');options('rarity',cfg.rarities.map(r=>[r,r]),'RARE');familyControls();options('appearance',cfg.modes.map(m=>[m,m]),'RECOGNIZABLE');for(const [id,prefix,def] of [['camera','T01','T01.02'],['lighting','T03','T03.01'],['glyph','T05','T05.10']])options(id,cfg.traits.filter(t=>t.id.startsWith(prefix+'.')).map(t=>[t.id,t.label]),def);options('profile',cfg.config.legends.map((s,i)=>[String(i),s]),'0');options('source-concepts',registry.traits.filter(t=>t.families.length===1).map(t=>[t.id,t.id+' · '+t.label]));options('fusion-operator',[['','DNA selected'],...(recipes.operators||[]).map(x=>[x,x.replaceAll('_',' ')])],'');options('rendering-profile',['SCULPTURAL','ANATOMICAL','GEOMETRIC','ORGANIC','FRACTURED','CRYPTIC','MINIMAL','VOID','CHAOTIC'].map(x=>[x,x]),'SCULPTURAL');$('category-controls').innerHTML=CATEGORIES.map(c=>'<label>'+c+'<select id="cat-'+c+'"></select></label>').join('');for(const c of CATEGORIES)options('cat-'+c,[['','Deterministic synthesis'],...registry.traits.filter(t=>t.category===c).map(t=>[t.id,t.label])],'');options('filter-family',[['','All source influences'],...cfg.families.map(f=>[f,f])]);options('filter-rarity',[['','All rarities'],...cfg.rarities.map(r=>[r,r])]);options('filter-trait',[['','All curated traits'],...registry.traits.map(t=>[t.id,t.id+' · '+t.label])]);versionControls();await status();await recent();if(studio.release!=='legacy')packet(await studio.api('/api/item?edition=1'),1);else if(studio.experiments.items?.length)packet(await studio.experiment(studio.experiments.items[0].id||studio.experiments.items[0].experimental_id));else packet(await studio.api('/api/item?edition=6'),6);const view=location.hash.slice(1);if(['lab','dna','animation','collection','analytics','traits','experiments'].includes(view))show(view);});

$('migrate-dna').onclick=()=>current&&task(async()=>{let input=current;if(current.dna?.algorithm&&!input.genome.scene)input=await studio.api('/api/decode',{envelope:current.dna});packet(await studio.api('/api/migrate',{genome:input.genome,options:{grid:Number($('native-grid').value),hiddenMessage:input.hiddenMessage}}));show('lab');await status();});

function sourceSelection(){const ids=[...$('source-concepts').selectedOptions].map(o=>o.textContent);$('source-selection').textContent=ids.length?ids.join(' · '):'Random source synthesis';}
$('source-concepts').onchange=sourceSelection;
